import{_ as p,a0 as o,w as d,s as h,ao as i,I as a,x as n,a1 as l,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Bash 腳本中添加註釋 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Bash 腳本中添加註釋 | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Bash 腳本中添加註釋 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Bash 腳本中添加註釋 | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20231010 How to Add Comments in Bash Scripts","title":"如何在 Bash 腳本中添加註釋","tag":"202310","desc":""},"relativePath":"202310/20231010 How to Add Comments in Bash Scripts.md","filePath":"[post].md"}'),r={name:"202310/20231010 How to Add Comments in Bash Scripts.md"};function u(b,s,g,m,c,k){const e=o("Link");return d(),h("div",null,[s[28]||(s[28]=i(`<h1 id="如何在-bash-腳本中添加註釋" tabindex="-1">如何在 Bash 腳本中添加註釋 <a class="header-anchor" href="#如何在-bash-腳本中添加註釋" aria-label="Permalink to “如何在 Bash 腳本中添加註釋”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202310/19/113658dld7b9987xa89l99.jpg" alt=""></p><blockquote><p>你有要説明的地方嗎？請將它們添加到你的 Bash 腳本中。</p></blockquote><p>在 Bash 腳本中添加註釋是保持代碼整潔且易於理解的最有效方法之一。</p><p>你可能會問為什麼。</p><p>假設你的腳本包含一個複雜的正則表達式或多個複雜的代碼塊，在這種情況下，你可以添加註釋，以便其他開發人員或你可以瞭解該代碼塊的含義。</p><p>註釋掉部分代碼也有助於調試腳本。</p><p>在本教程中，我將引導你瞭解在 Bash 腳本中添加註釋的三種方法：</p><ul><li>單行註釋</li><li>行內評論</li><li>多行註釋</li></ul><p>那麼讓我們從第一個開始。</p><h3 id="bash-中的單行註釋" tabindex="-1">Bash 中的單行註釋 <a class="header-anchor" href="#bash-中的單行註釋" aria-label="Permalink to “Bash 中的單行註釋”">​</a></h3><p>要添加單行註釋，你必須將哈希符號（<code>#</code>）放在行的開頭並編寫註釋。</p><p>這是一個簡單的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span># This is a comment</span></span>
<span class="line"><span>echo &quot;Hello, World!&quot;</span></span></code></pre></div><p>執行時，註釋將被忽略，當我執行上面的命令時，它看起來像這樣：</p><p><img src="https://itsfoss.com/content/images/2023/10/Use-single-line-comments-in-bash.png" alt=""></p>`,16)),a("blockquote",null,[a("p",null,[s[1]||(s[1]=n("💡 ",-1)),s[2]||(s[2]=a("code",null,"#",-1)),s[3]||(s[3]=n(" 註釋規則的唯一例外是腳本開頭的 ",-1)),s[4]||(s[4]=a("code",null,"#!/bin/bash",-1)),s[5]||(s[5]=n(" 行。它稱為 ",-1)),l(e,{href:"https://linux.cn/article-3664-1.html"},{default:t(()=>[...s[0]||(s[0]=[n("釋伴",-1)])]),_:1}),s[6]||(s[6]=n("，用於指定運行腳本時要使用的解釋器。有不同的 Shell，語法也可能不同。因此，一個好的做法是指定腳本是為哪個 Shell 編寫的。例如，如果是 ksh，則可以使用 ",-1)),s[7]||(s[7]=a("code",null,"#!/bin/ksh",-1)),s[8]||(s[8]=n(".",-1))])]),s[29]||(s[29]=i(`<h3 id="bash-腳本中的內聯註釋" tabindex="-1">Bash 腳本中的內聯註釋 <a class="header-anchor" href="#bash-腳本中的內聯註釋" aria-label="Permalink to “Bash 腳本中的內聯註釋”">​</a></h3><p>或者，你可以將註釋放在代碼塊內以記錄該特定行的用途。</p><blockquote><p>🚧 <code>#</code> 之後的任何內容在該行結束之前都不會執行，因此請確保在代碼末尾添加註釋。</p></blockquote><p>這是一個簡單的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>echo &quot;Hello, World!&quot; #Prints hello world</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/10/How-to-use-the-single-line-comments-in-bash.png" alt=""></p><h3 id="bash-中的多行註釋" tabindex="-1">Bash 中的多行註釋 <a class="header-anchor" href="#bash-中的多行註釋" aria-label="Permalink to “Bash 中的多行註釋”">​</a></h3><blockquote><p>🚧 Bash 中沒有內置的多行註釋功能。但是，有一些解決方法可以實現多行註釋效果。</p></blockquote><p>顧名思義，Bash 腳本中的多行註釋允許你在多行中編寫註釋，或者通過將它們放在多行註釋部分來阻止執行代碼塊：</p>`,9)),a("ol",null,[s[11]||(s[11]=a("li",null,[n("在每行的開頭使用 "),a("code",null,"#")],-1)),a("li",null,[l(e,{href:"https://stackoverflow.com/questions/3224878/what-is-the-purpose-of-the-colon-gnu-bash-builtin"},{default:t(()=>[...s[9]||(s[9]=[n("冒號表示法",-1)])]),_:1}),s[10]||(s[10]=n("（使用冒號後跟單引號）",-1))]),s[12]||(s[12]=a("li",null,[n("現場文檔（使用 "),a("code",null,"<<"),n(" 後跟分隔符）")],-1))]),s[30]||(s[30]=i(`<p>那麼讓我們從第一個開始。</p><h4 id="_1、對塊註釋的每一行使用" tabindex="-1">1、對塊註釋的每一行使用 <code>#</code> <a class="header-anchor" href="#_1、對塊註釋的每一行使用" aria-label="Permalink to “1、對塊註釋的每一行使用 #”">​</a></h4><p>如果你的目的是解釋腳本的一部分，我建議使用此方法。畢竟，<code>#</code> 才是真正的註釋功能。</p><p>這也是許多開發人員使用的方法。</p><p>假設你必須在一開始就解釋腳本的用途、作者信息或許可信息。你可以這樣寫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>######################################</span></span>
<span class="line"><span>## This script is used for scanning ##</span></span>
<span class="line"><span>## local network                    ##</span></span>
<span class="line"><span>## Licensed under GPL 2.0           ##</span></span>
<span class="line"><span>######################################</span></span>
<span class="line"><span></span></span>
<span class="line"><span>這個 Bash 腳本的其它部分……</span></span></code></pre></div><p>當你想説明 Bash 腳本的行為方式時這不錯。如果你正在調試 Bash 腳本並希望隱藏部分腳本，則在所需代碼的每一行開頭添加 <code>#</code> 並在調試後將其刪除是一項耗時的任務。</p><p>接下來的兩節將幫助你做到這一點。</p><h4 id="_2、冒號表示法" tabindex="-1">2、冒號表示法 <a class="header-anchor" href="#_2、冒號表示法" aria-label="Permalink to “2、冒號表示法”">​</a></h4><p>要使用冒號表示法，請在 <code>: &#39;</code> 和結束的 <code>&#39;</code> 之間編寫塊註釋，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>: &#39;</span></span>
<span class="line"><span>This is how you can use colon notation</span></span>
<span class="line"><span>And this line too will be ignored</span></span>
<span class="line"><span>&#39;</span></span>
<span class="line"><span>echo &quot;GOODBYE&quot;</span></span></code></pre></div><p>當你執行上面的腳本時，它應該只打印 <code>GOODBYE</code>。</p><p><img src="https://itsfoss.com/content/images/2023/10/Use-multi-line-comments-using-colon-notation-in-bash.png" alt=""></p><h4 id="_3、現場文檔" tabindex="-1">3、現場文檔 <a class="header-anchor" href="#_3、現場文檔" aria-label="Permalink to “3、現場文檔”">​</a></h4><p>到目前為止，這是在 Bash 中編寫多行註釋的最流行的方法，你可以使用 <code>&lt;&lt;</code> 後跟分隔符（一組用於指定註釋開始和結束的字符）。</p><p>（LCTT 譯註：在編程領域，“<strong>here document</strong>” 是一個常見的術語，特指在腳本語言（如 Perl、Bash）中，能夠直接在代碼內部嵌入並處理一個數據塊或文本串的技術。儘管傳統上我們將它翻譯為“嵌入式文檔” 或不翻譯，但這個譯法似乎並不能完全地體現出原文的感覺和含義。為了讓這個概念變得更為直觀和易理解，我們建議將 “here document” 翻譯為 “<strong>現場文檔</strong>”。“現場”相比於“嵌入式”，更好的傳達了文檔就在代碼的當前位置，或代碼“現場”的含義。這樣的譯法也與原文 “here document” 中 “here”（這裏）的含義更為契合。我們希望這個譯法能夠在未來得到更廣泛的使用和認可，讓編程的世界因語言的精準而變得更美好。PS., 該譯法和解釋得到了 ChatGPT 的建議和生成。）</p><p>使用方法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;&lt;DELIMITER</span></span>
<span class="line"><span>Comment line 1</span></span>
<span class="line"><span>Comment line 2</span></span>
<span class="line"><span>DELIMITER</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;Hello, World!&quot;</span></span></code></pre></div><p>還困惑嗎？ 這是一個簡單的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;&lt;COMMENT</span></span>
<span class="line"><span>This is a multi-line comment using a here document.</span></span>
<span class="line"><span>You can add as many lines as you want between &lt;&lt;COMMENT and the terminating keyword.</span></span>
<span class="line"><span>This block won&#39;t be executed by the shell.</span></span>
<span class="line"><span>COMMENT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;Hello, World!&quot;</span></span></code></pre></div><p>在上面的示例中，我使用了 <code>COMMENT</code> 作為分隔符，但你可以使用任何內容，但要確保它從註釋中脱穎而出，否則會造成混亂。</p><p>當我執行上面的腳本時，它給出了以下輸出：</p><p><img src="https://itsfoss.com/content/images/2023/10/Use-multi-line-comments-in-bash-using----and-delimeter.png" alt=""></p><p>正如你所看到的，它忽略了從 <code>&lt;&lt;COMMENT</code> 到 <code>COMMENT</code> 的所有內容。</p><p>我希望本指南對你有所幫助。</p><p><em>（題圖：MJ/7c2a3ef4-5256-405e-b757-23e0ba1f0bc5）</em></p><hr>`,27)),a("p",null,[s[14]||(s[14]=n("via: ",-1)),l(e,{href:"https://itsfoss.com/bash-comments/"},{default:t(()=>[...s[13]||(s[13]=[n("https://itsfoss.com/bash-comments/",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=n("作者：",-1)),l(e,{href:"https://itsfoss.com/author/sagar/"},{default:t(()=>[...s[15]||(s[15]=[n("Sagar Sharma",-1)])]),_:1}),s[20]||(s[20]=n(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[16]||(s[16]=[n("lujun9972",-1)])]),_:1}),s[21]||(s[21]=n(" 譯者：",-1)),l(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[17]||(s[17]=[n("geekpi",-1)])]),_:1}),s[22]||(s[22]=n(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[18]||(s[18]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[25]||(s[25]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[23]||(s[23]=[n("LCTT",-1)])]),_:1}),s[26]||(s[26]=n(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:t(()=>[...s[24]||(s[24]=[n("Linux中國",-1)])]),_:1}),s[27]||(s[27]=n(" 榮譽推出",-1))])])}const B=p(r,[["render",u]]);export{C as __pageData,B as default};
